mapper.select:
SELECT profile_identifier_id AS profileIdentifierId, profile_id AS profileId, identity_key_id AS identityKeyId,
  issuer_scope_key AS issuerScopeKey
FROM t_party_profile_identifier WHERE profile_id=#{profileId}

mapper.update:
UPDATE t_party_profile_identifier
SET identity_key_id=#{identityKeyId}, issuer_scope_key=#{issuerScopeKey}, update_time=#{now}
WHERE profile_identifier_id=#{identifier.profileIdentifierId}
  AND identity_key_id IS NULL
  identity_key_id=#{identifier.identityKeyId}
